#nullable enable
using Marten;
using EmailOutbox.Contracts;

namespace EmailOutbox.Slices.EmailOutbox;

/// <summary>
/// THE DECIDER for <see cref="SendEmail"/>: it receives the folded state and returns the event. Same job an
/// HTTP endpoint does for a command somebody types, in a different transport.
///
/// It is a Wolverine MESSAGE handler and not an endpoint because **nobody types this command**. The trigger
/// issues it in-process. Giving it an HTTP route would invent public surface the model does not draw — and
/// would also make the automation look runnable when the thing that runs it is missing.
///
/// Both of this slice's rules live here rather than in a validator, because both need the stream:
///
///   NotPrepared   the stream has no EmailPrepared — which is also what an entirely absent email looks
///                 like, so one check covers both
///   AlreadySent   an EmailSent is already on the stream. THIS IS THE LOAD-BEARING ONE. Every wakeup
///                 mechanism in this folder is at-least-once, so without it, comparing them would be
///                 comparing four different ways of sending duplicate email.
///
/// The rules are enforced against a fold taken inside the transaction, so two concurrent sends cannot both
/// pass: <c>FetchForWriting</c> takes the stream's version and the append fails on a mismatch.
/// </summary>
public static class SendEmailHandler
{
    /// <summary>What the trigger reads back. See <see cref="SendOutcome"/> for why it is not ProblemDetails.</summary>
    public static async Task<SendOutcome> Handle(
        SendEmail command,
        IDocumentSession session,
        CancellationToken cancellation)
    {
        var stream = await session.Events.FetchForWriting<SendEmailState>(
            SendEmailState.StreamKey(command.EmailId), cancellation);
        var email = stream.Aggregate ?? new SendEmailState();

        if (!email.Prepared)
            return SendOutcome.Rejected("NotPrepared",
                $"No email {command.EmailId} has been prepared, so there is nothing to send.");

        if (email.Sent)
            return SendOutcome.Rejected("AlreadySent",
                $"Email {command.EmailId} has already been sent. At-least-once delivery makes this the normal case, not an error in the caller.");

        // terminal="providerMessageId:generated" and terminal="sentAt:clock" — both come from the handler,
        // not from the data flow, which is what the model's terminal= records. In a real system this is
        // where the provider call goes, and the id is whatever it hands back.
        var providerMessageId = $"prov-{Guid.NewGuid():n}";

        stream.AppendOne(new EmailSent(command.EmailId, providerMessageId, DateTimeOffset.UtcNow));
        await session.SaveChangesAsync(cancellation);

        return SendOutcome.Delivered(command.EmailId, providerMessageId);
    }
}

/// <summary>
/// What the decider answers the trigger with, and the reason it is not <c>ProblemDetails</c>: an automation
/// has **no HTTP caller** to hand one to. The generated test scaffold guessed at "a 400 with ProblemDetails"
/// because the generator cannot tell an automation's command from a typed one — a real limitation, noted
/// rather than worked around.
///
/// The invariant that does hold across every transport is that <see cref="Rule"/> carries the model's rule
/// name verbatim. A GWT says <c>then="error: AlreadySent"</c>, so the name is the machine-readable half and
/// the prose is for a human.
/// </summary>
public sealed record SendOutcome(Guid? EmailId, string? ProviderMessageId, string? Rule, string? Detail)
{
    public bool WasSent => Rule is null;

    public static SendOutcome Delivered(Guid emailId, string providerMessageId) =>
        new(emailId, providerMessageId, null, null);

    public static SendOutcome Rejected(string rule, string detail) => new(null, null, rule, detail);
}
